// Calculate Days & Risk: stage mapping, SLA-based risk tiers, tiered revenue-at-risk
const stageNameMap = {
  appointmentscheduled: 'Qualified Lead',
  qualifiedtobuy: 'Discovery',
  presentationscheduled: 'Proposal/Demo',
  decisionmakerboughtin: 'Negotiation',
  closedwon: 'Closed Won',
  closedlost: 'Closed Lost'
};

// SLA thresholds in days
const slaThresholds = {
  'Qualified Lead': 5,
  'Discovery': 5,
  'Proposal/Demo': 21,
  'Negotiation': 14
};

// Loss probabilities per risk tier (estimates; validate against historical close rates)
const lossProbability = {
  HIGH: 0.40,   // past SLA
  MEDIUM: 0.15, // past 70% of SLA
  OK: 0
};

const MS_PER_DAY = 1000 * 60 * 60 * 24;
const today = new Date();

// Accepts epoch milliseconds (number or numeric string) or an ISO date string
const parseHubSpotDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const str = String(value).trim();
  const date = /^\d+$/.test(str) ? new Date(Number(str)) : new Date(str);
  return isNaN(date.getTime()) ? null : date;
};

return $input.all().map(deal => {
  const props = deal.json.properties || {};

  const deal_id = deal.json.dealId;
  const deal_name = props.dealname?.value || 'N/A';
  const stage_id = props.dealstage?.value || 'Unknown';
  const stage = stageNameMap[stage_id] || 'Unknown Stage';
  const amount = parseFloat(props.amount?.value || 0) || 0;
  const stage_entry_date = props.hs_v2_date_entered_current_stage?.value || null;
  const owner_id = props.hubspot_owner_id?.value || null;

  // Days in current stage
  const stage_date = parseHubSpotDate(stage_entry_date);
  const days_in_stage = stage_date ? Math.floor((today - stage_date) / MS_PER_DAY) : 0;

  const sla_threshold = slaThresholds[stage] ?? null;

  // Data quality flag: open deal without a usable stage entry date
  const isClosed = stage === 'Closed Won' || stage === 'Closed Lost';
  const data_issue = !isClosed && !stage_date ? 'missing_stage_entry_date' : null;

  // Risk tier
  let risk_level;
  if (isClosed) risk_level = 'CLOSED';
  else if (sla_threshold === null || !stage_date) risk_level = 'UNKNOWN'; // unknown stage or missing entry date
  else if (days_in_stage > sla_threshold) risk_level = 'HIGH';
  else if (days_in_stage > sla_threshold * 0.7) risk_level = 'MEDIUM';
  else risk_level = 'OK';

  // Tiered revenue at risk
  const revenue_at_risk = amount * (lossProbability[risk_level] || 0);

  return {
    json: {
      deal_id,
      deal_name,
      stage,
      stage_id,
      amount,
      stage_entry_date,
      owner_id,
      days_in_stage,
      sla_threshold,
      risk_level,
      revenue_at_risk,
      data_issue,
      stage_date: stage_date ? stage_date.toISOString().split('T')[0] : null
    }
  };
});

// Create Summary: risk counts, tiered revenue-at-risk, prioritized top-3 deals
const deals = $input.all().map(d => d.json);
const CURRENCY = '€'; // HubSpot amounts are EUR in the Flowbase data; switch to '$' if needed
const fmt = n => CURRENCY + Math.round(n || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const sumRisk = list => list.reduce((sum, d) => sum + d.revenue_at_risk, 0);

const highRiskDeals = deals.filter(d => d.risk_level === 'HIGH');
const mediumRiskDeals = deals.filter(d => d.risk_level === 'MEDIUM');

const highRiskCount = highRiskDeals.length;
const mediumRiskCount = mediumRiskDeals.length;
const totalAtRisk = highRiskCount + mediumRiskCount;

const highRiskRevenue = Math.round(sumRisk(highRiskDeals));
const mediumRiskRevenue = Math.round(sumRisk(mediumRiskDeals));
const totalRevenueAtRisk = highRiskRevenue + mediumRiskRevenue;

// Priority: HIGH before MEDIUM, then revenue at risk, then days in stage
const tierRank = { HIGH: 2, MEDIUM: 1 };
const topRiskDeals = [...highRiskDeals, ...mediumRiskDeals]
  .sort((a, b) =>
    (tierRank[b.risk_level] - tierRank[a.risk_level]) ||
    (b.revenue_at_risk - a.revenue_at_risk) ||
    (b.days_in_stage - a.days_in_stage)
  )
  .slice(0, 3);

// Pre-built Slack text: works with 0, 1, 2 or 3 at-risk deals
const rankEmoji = ['1️⃣', '2️⃣', '3️⃣'];
const topDealsText = topRiskDeals.length
  ? topRiskDeals.map((d, i) =>
      `${rankEmoji[i]} *${d.deal_name}* [${d.risk_level}]\n` +
      `• Stage: ${d.stage} (${d.days_in_stage} days, SLA ${d.sla_threshold}) | Amount: ${fmt(d.amount)} | Owner: ${d.owner_id || 'Unassigned'}`
    ).join('\n')
  : '✅ No deals at risk this week';

return {
  json: {
    totalAtRisk,
    highRiskCount,
    mediumRiskCount,
    highRiskRevenue,
    mediumRiskRevenue,
    totalRevenueAtRisk,
    highRiskRevenueFormatted: fmt(highRiskRevenue),
    mediumRiskRevenueFormatted: fmt(mediumRiskRevenue),
    totalRevenueAtRiskFormatted: fmt(totalRevenueAtRisk),
    topRiskDeals,
    topDealsText
  }
};

// Calculate Trend: week-over-week at-risk comparison (history from Google Sheets)
const summary = $('Create Summary1').first().json;
const currentAtRisk = summary.totalAtRisk || 0;
const todayStr = $today.toFormat('yyyy-MM-dd');

// Sheet rows: drop empty rows and today's row (so manual re-runs don't compare against themselves)
const history = $input.all()
  .map(item => item.json)
  .filter(r =>
    r['At-Risk Count'] !== undefined &&
    r['At-Risk Count'] !== '' &&
    String(r['Week Of']) !== todayStr
  );

const lastRow = history.length ? history[history.length - 1] : null;
const previousWeekAtRisk = lastRow ? Number(lastRow['At-Risk Count']) : null;

let trend = 0, trendPercent = 0, trendEmoji, trendLabel, trendString;

if (previousWeekAtRisk === null || Number.isNaN(previousWeekAtRisk)) {
  // First run: no history yet
  trendEmoji = '⚪';
  trendLabel = 'Baseline';
  trendString = '⚪ Baseline week (no history yet)';
} else {
  trend = currentAtRisk - previousWeekAtRisk;
  trendPercent = previousWeekAtRisk > 0
    ? Math.round((trend / previousWeekAtRisk) * 100)
    : 0;

  if (trend > 0)      { trendEmoji = '🔴'; trendLabel = 'Worse'; }
  else if (trend < 0) { trendEmoji = '🟢'; trendLabel = 'Better'; }
  else                { trendEmoji = '⚪'; trendLabel = 'Flat'; }

  trendString = trend !== 0
    ? `${trendEmoji} ${trend > 0 ? '+' : ''}${trend} deals (was ${previousWeekAtRisk})`
    : `${trendEmoji} Flat (was ${previousWeekAtRisk} deals)`;
}

return {
  json: {
    ...summary,
    currentAtRisk,
    previousWeekAtRisk,
    trend,
    trendPercent,
    trendEmoji,
    trendLabel,
    trendString
  }
};

// Calculate Stage Stats: avg days-in-stage, per-stage risk, bottlenecks vs SLA
const deals = $input.all().map(d => d.json);
const CURRENCY = '€'; // HubSpot amounts are EUR in the Flowbase data; switch to '$' if needed
const fmt = n => CURRENCY + Math.round(n || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const stages = ['Qualified Lead', 'Discovery', 'Proposal/Demo', 'Negotiation'];
const slaThresholds = {
  'Qualified Lead': 5,
  'Discovery': 5,
  'Proposal/Demo': 21,
  'Negotiation': 14
};

const stageStats = {};
let slowestStage = null, slowestAvgDays = 0;
let fastestStage = null, fastestAvgDays = Infinity;

stages.forEach(stage => {
  const stageDeals = deals.filter(
    d => d.stage === stage && d.risk_level !== 'CLOSED' && d.risk_level !== 'UNKNOWN'
  );
  const highDeals = stageDeals.filter(d => d.risk_level === 'HIGH');
  const mediumDeals = stageDeals.filter(d => d.risk_level === 'MEDIUM');
  const okDeals = stageDeals.filter(d => d.risk_level === 'OK');
  const sumRisk = list => list.reduce((sum, d) => sum + d.revenue_at_risk, 0);

  const avgDays = stageDeals.length
    ? Math.round(stageDeals.reduce((sum, d) => sum + d.days_in_stage, 0) / stageDeals.length)
    : 0;

  stageStats[stage] = {
    avgDays,
    dealCount: stageDeals.length,
    highRisk: highDeals.length,
    mediumRisk: mediumDeals.length,
    ok: okDeals.length,
    atRiskCount: highDeals.length + mediumDeals.length,
    highRiskRevenue: Math.round(sumRisk(highDeals)),
    mediumRiskRevenue: Math.round(sumRisk(mediumDeals)),
    stageRevenueAtRisk: Math.round(sumRisk(stageDeals))
  };

  if (stageDeals.length) {
    if (avgDays > slowestAvgDays) { slowestAvgDays = avgDays; slowestStage = stage; }
    if (avgDays < fastestAvgDays) { fastestAvgDays = avgDays; fastestStage = stage; }
  }
});
if (fastestStage === null) fastestAvgDays = 0;

// Bottlenecks: stage average above SLA
const bottlenecks = stages
  .filter(stage => stageStats[stage].dealCount > 0 && stageStats[stage].avgDays > slaThresholds[stage])
  .map(stage => ({
    stage,
    avgDays: stageStats[stage].avgDays,
    sla: slaThresholds[stage],
    daysOverSla: stageStats[stage].avgDays - slaThresholds[stage],
    dealCount: stageStats[stage].dealCount,
    atRiskCount: stageStats[stage].atRiskCount,
    highRiskRevenue: stageStats[stage].highRiskRevenue,
    mediumRiskRevenue: stageStats[stage].mediumRiskRevenue
  }))
  .sort((a, b) => b.daysOverSla - a.daysOverSla);

const bottleneckWarnings = bottlenecks
  .map(b => `• ${b.stage}: ${b.avgDays} days avg (SLA: ${b.sla}, +${b.daysOverSla} days over)`)
  .join('\n');

// Pre-built Slack text blocks
const stageBreakdownText = stages
  .map(stage => {
    const s = stageStats[stage];
    return `• ${stage}: ${s.atRiskCount} at risk of ${s.dealCount} open (HIGH: ${fmt(s.highRiskRevenue)})`;
  })
  .join('\n');

const pipelineHealthText = slowestStage
  ? `• Slowest: ${slowestStage} (avg ${slowestAvgDays} days)\n• Fastest: ${fastestStage} (avg ${fastestAvgDays} days)`
  : '• No open deals in tracked stages';

const bottleneckText = bottlenecks.length
  ? `⚠️ ${bottlenecks.length} bottleneck${bottlenecks.length > 1 ? 's' : ''} (stage avg above SLA):\n${bottleneckWarnings}`
  : '✅ No bottlenecks: all stages within SLA on average';

return {
  json: {
    stageStats,
    slowestStage,
    slowestAvgDays,
    fastestStage,
    fastestAvgDays,
    bottleneckCount: bottlenecks.length,
    bottlenecks,
    bottleneckWarnings,
    stageBreakdownText,
    pipelineHealthText,
    bottleneckText
  }
};

